import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    Expects 0 <= x <= 255 and 0 <= k <= 7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_simple_wrap() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_no_wrap() -> None:
    assert rotl8(0b00000011, 2) == 0b00001100


def test_rotl8_zero_shift_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x


def test_rotl8_max_shift() -> None:
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b10000000, 7) == 0b01000000


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_known_values() -> None:
    assert rotl8(0xA5, 4) == 0x5A
    assert rotl8(0xF0, 4) == 0x0F
    assert rotl8(0x12, 3) == 0x90


@pytest.mark.parametrize("k", range(8))
def test_rotl8_matches_string_reference(k: int) -> None:
    for x in range(256):
        s = f"{x:08b}"
        expected = int(s[k:] + s[:k], 2)
        assert rotl8(x, k) == expected


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x if 8 - k <= 7 else True


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
